import React from 'react';
import PublicLayout, { PublicThemeProps } from './PublicLayout';
export interface StaticDocument { slug: string; title: string; html: string; description?: string; schemaType?: string }
export default function StaticPage({ page, ...theme }: PublicThemeProps & { page: StaticDocument }) {
  return <PublicLayout {...theme}><article className="public-article home-width"><h1>{page.title}</h1><div className="article-body" dangerouslySetInnerHTML={{ __html: page.html }} /></article></PublicLayout>;
}
